"""Fusion 360 script: chip chip1_triculture_dissociation_quench_cell_wash_filter (59 x 50 mm), generated by autochip/cad.py from chips/chip1_triculture_dissociation_quench_cell_wash_filter.json.
Run it in Fusion: Utilities > Scripts and Add-Ins, or send it through the Fusion MCP execute_code tool
(then set PARTS_DIR first). It
  1. imports every placed part (parts/<module>.stl, mm, chip origin) as its own component,
  2. sketches the board outline, the port circles and every channel centreline ("channel paths"),
  3. sketches every channel as a closed outline at its true width ("channel outlines"), ready to
     extrude-cut 0.3 mm into the fluidic layer (top of the fluidic layer at z = 1.5 mm).
Fusion's API works in cm; the numbers below are mm and converted on the way in.
"""
import adsk.core, adsk.fusion
import os

try:
    PARTS_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "parts")
except NameError:
    PARTS_DIR = globals()["PARTS_DIR"]
BOARD = [59.0, 50.0]
PARTS = [["split_1", "splitter"], ["culture_neurons", "culture_chamber_param"], ["culture_microglia", "culture_chamber_param"], ["culture_astrocytes", "culture_chamber_param"], ["junction_mid", "pool"], ["quench_join", "merge"], ["quench_mix", "mixer"], ["cell_wash", "spiral_separator"], ["cell_filter", "pillar_filter"]]
CHANNELS = [["ch_inlet_1_split_1", 0.25, [[2.0, 25.0], [2.5, 25.0], [4.3, 25.0]]], ["ch_junction_mid_quench_join", 0.3, [[30.3, 25.0], [31.9, 25.0]]], ["ch_quench_join_quench_mix", 0.3, [[33.7, 25.0], [35.3, 25.0]]], ["ch_quench_mix_cell_wash", 0.3, [[37.9, 25.0], [38.9, 25.0]]], ["ch_cell_wash_cell_filter", 0.3, [[51.7, 25.0], [52.7, 25.0]]], ["ch_cell_filter_outlet_1", 0.3, [[54.7, 25.0], [56.5, 25.0], [57.0, 25.0]]], ["ch_split_1_culture_neurons", 0.2, [[6.3, 40.0], [7.3, 40.0]]], ["ch_split_1_culture_microglia", 0.2, [[6.3, 25.0], [7.3, 25.0]]], ["ch_split_1_culture_astrocytes", 0.2, [[6.3, 10.0], [7.3, 10.0]]], ["ch_culture_neurons_junction_mid", 0.3, [[27.3, 40.0], [28.3, 40.0]]], ["ch_culture_microglia_junction_mid", 0.3, [[27.3, 25.0], [28.3, 25.0]]], ["ch_culture_astrocytes_junction_mid", 0.3, [[27.3, 10.0], [28.3, 10.0]]], ["ch_culture_medium_neurons_in_culture_neurons", 0.25, [[17.3, 46.5], [17.3, 46.0], [17.3, 45.0]]], ["ch_culture_neurons_culture_neurons_vent_out", 0.25, [[17.3, 35.0], [17.3, 34.0], [17.3, 33.5]]], ["ch_culture_medium_microglia_in_culture_microglia", 0.25, [[17.3, 31.5], [17.3, 31.0], [17.3, 30.0]]], ["ch_culture_microglia_microglia_vent_out", 0.25, [[15.8, 20.0], [15.8, 19.0], [15.8, 18.5]]], ["ch_culture_microglia_culture_microglia_vent_out", 0.25, [[18.8, 20.0], [18.8, 19.0], [18.8, 18.5]]], ["ch_culture_medium_astrocytes_in_culture_astrocytes", 0.25, [[17.3, 16.5], [17.3, 16.0], [17.3, 15.0]]], ["ch_culture_astrocytes_astrocytes_vent_out", 0.25, [[15.8, 5.0], [15.8, 4.0], [15.8, 3.5]]], ["ch_culture_astrocytes_culture_astrocytes_vent_out", 0.25, [[18.8, 5.0], [18.8, 4.0], [18.8, 3.5]]], ["ch_quench_solution_in_quench_join", 0.25, [[32.8, 48.0], [32.8, 47.5], [32.8, 25.9]]], ["ch_wash_buffer_in_cell_wash", 0.25, [[45.3, 48.0], [45.3, 47.5], [45.3, 31.4]]], ["ch_cell_wash_cell_wash_waste_out", 0.25, [[45.3, 18.6], [45.3, 2.5], [45.3, 2.0]]]]
OUTLINES = [["ch_inlet_1_split_1", [[2.0, 25.125], [4.3, 25.125], [4.3, 24.875], [2.0, 24.875]]], ["ch_junction_mid_quench_join", [[30.3, 25.15], [31.9, 25.15], [31.9, 24.85], [30.3, 24.85]]], ["ch_quench_join_quench_mix", [[33.7, 25.15], [35.3, 25.15], [35.3, 24.85], [33.7, 24.85]]], ["ch_quench_mix_cell_wash", [[37.9, 25.15], [38.9, 25.15], [38.9, 24.85], [37.9, 24.85]]], ["ch_cell_wash_cell_filter", [[51.7, 25.15], [52.7, 25.15], [52.7, 24.85], [51.7, 24.85]]], ["ch_cell_filter_outlet_1", [[54.7, 25.15], [57.0, 25.15], [57.0, 24.85], [54.7, 24.85]]], ["ch_split_1_culture_neurons", [[6.3, 40.1], [7.3, 40.1], [7.3, 39.9], [6.3, 39.9]]], ["ch_split_1_culture_microglia", [[6.3, 25.1], [7.3, 25.1], [7.3, 24.9], [6.3, 24.9]]], ["ch_split_1_culture_astrocytes", [[6.3, 10.1], [7.3, 10.1], [7.3, 9.9], [6.3, 9.9]]], ["ch_culture_neurons_junction_mid", [[27.3, 40.15], [28.3, 40.15], [28.3, 39.85], [27.3, 39.85]]], ["ch_culture_microglia_junction_mid", [[27.3, 25.15], [28.3, 25.15], [28.3, 24.85], [27.3, 24.85]]], ["ch_culture_astrocytes_junction_mid", [[27.3, 10.15], [28.3, 10.15], [28.3, 9.85], [27.3, 9.85]]], ["ch_culture_medium_neurons_in_culture_neurons", [[17.425, 46.5], [17.425, 45.0], [17.175, 45.0], [17.175, 46.5]]], ["ch_culture_neurons_culture_neurons_vent_out", [[17.425, 35.0], [17.425, 33.5], [17.175, 33.5], [17.175, 35.0]]], ["ch_culture_medium_microglia_in_culture_microglia", [[17.425, 31.5], [17.425, 30.0], [17.175, 30.0], [17.175, 31.5]]], ["ch_culture_microglia_microglia_vent_out", [[15.925, 20.0], [15.925, 18.5], [15.675, 18.5], [15.675, 20.0]]], ["ch_culture_microglia_culture_microglia_vent_out", [[18.925, 20.0], [18.925, 18.5], [18.675, 18.5], [18.675, 20.0]]], ["ch_culture_medium_astrocytes_in_culture_astrocytes", [[17.425, 16.5], [17.425, 15.0], [17.175, 15.0], [17.175, 16.5]]], ["ch_culture_astrocytes_astrocytes_vent_out", [[15.925, 5.0], [15.925, 3.5], [15.675, 3.5], [15.675, 5.0]]], ["ch_culture_astrocytes_culture_astrocytes_vent_out", [[18.925, 5.0], [18.925, 3.5], [18.675, 3.5], [18.675, 5.0]]], ["ch_quench_solution_in_quench_join", [[32.925, 48.0], [32.925, 25.9], [32.675, 25.9], [32.675, 48.0]]], ["ch_wash_buffer_in_cell_wash", [[45.425, 48.0], [45.425, 31.4], [45.175, 31.4], [45.175, 48.0]]], ["ch_cell_wash_cell_wash_waste_out", [[45.425, 18.6], [45.425, 2.0], [45.175, 2.0], [45.175, 18.6]]]]
PORTS = [["inlet_1", 2.5, 25.0, 1.0], ["outlet_1", 56.5, 25.0, 1.0], ["culture_medium_neurons_in", 17.3, 46.0, 1.0], ["culture_neurons_vent_out", 17.3, 34.0, 1.0], ["culture_medium_microglia_in", 17.3, 31.0, 1.0], ["microglia_vent_out", 15.8, 19.0, 1.0], ["culture_microglia_vent_out", 18.8, 19.0, 1.0], ["culture_medium_astrocytes_in", 17.3, 16.0, 1.0], ["astrocytes_vent_out", 15.8, 4.0, 1.0], ["culture_astrocytes_vent_out", 18.8, 4.0, 1.0], ["quench_solution_in", 32.8, 47.5, 1.0], ["wash_buffer_in", 45.3, 47.5, 1.0], ["cell_wash_waste_out", 45.3, 2.5, 1.0]]


def P(xy, z=0.0):
    return adsk.core.Point3D.create(xy[0] / 10.0, xy[1] / 10.0, z / 10.0)


def run(context=None):
    app = adsk.core.Application.get()
    design = adsk.fusion.Design.cast(app.activeProduct)
    root = design.rootComponent
    for module_id, part in PARTS:
        occ = root.occurrences.addNewComponent(adsk.core.Matrix3D.create())
        comp = occ.component
        comp.name = module_id + " (" + part + ")"
        path = os.path.join(PARTS_DIR, module_id + ".stl")
        if design.designType == adsk.fusion.DesignTypes.ParametricDesignType:
            base = comp.features.baseFeatures.add()
            base.startEdit()
            comp.meshBodies.add(path, adsk.fusion.MeshUnits.MillimeterMeshUnit, base)
            base.finishEdit()
        else:
            comp.meshBodies.add(path, adsk.fusion.MeshUnits.MillimeterMeshUnit)
    sk = root.sketches.add(root.xYConstructionPlane)
    sk.name = "chip1_triculture_dissociation_quench_cell_wash_filter outline + ports + channel paths"
    lines = sk.sketchCurves.sketchLines
    lines.addTwoPointRectangle(P((0, 0)), P(BOARD))
    for pid, x, y, d in PORTS:
        sk.sketchCurves.sketchCircles.addByCenterRadius(P((x, y)), d / 20.0)
    for cid, width, pts in CHANNELS:
        for a, b in zip(pts[:-1], pts[1:]):
            lines.addByTwoPoints(P(a), P(b))
    sk2 = root.sketches.add(root.xYConstructionPlane)
    sk2.name = "chip1_triculture_dissociation_quench_cell_wash_filter channel outlines (true width)"
    for cid, pts in OUTLINES:
        for a, b in zip(pts, pts[1:] + pts[:1]):
            sk2.sketchCurves.sketchLines.addByTwoPoints(P(a), P(b))
    app.activeViewport.fit()
    return "imported %d parts, sketched %d channels and %d ports" % (len(PARTS), len(CHANNELS), len(PORTS))
